; ==================================================================
; SPRITE ANIMATION METADATA TABLES
; ==================================================================

; Table: Sprite Asset Frame Counts
; Format: db frame_count
sprite_asset_frame_count:
    db 4 ; Sprite 0: hero1_right
    db 5 ; Sprite 1: bird1
    db 6 ; Sprite 2: ball1
    db 4 ; Sprite 3: bird2
    db 2 ; Sprite 4: minipotato_right
    db 2 ; Sprite 5: blackDuck_left
    db 4 ; Sprite 6: hero1_left
    db 2 ; Sprite 7: minipotato_left
    db 2 ; Sprite 8: blackDuck_right
SPRITE_ASSET_COUNT EQU 9

; Table: Sprite Asset Loop Flags
; Format: db flags (bit 1: 1=loop, 0=once)
sprite_loop_flags:
    db 2 ; Sprite 0: hero1_right
    db 2 ; Sprite 1: bird1
    db 2 ; Sprite 2: ball1
    db 2 ; Sprite 3: bird2
    db 2 ; Sprite 4: minipotato_right
    db 2 ; Sprite 5: blackDuck_left
    db 2 ; Sprite 6: hero1_left
    db 2 ; Sprite 7: minipotato_left
    db 2 ; Sprite 8: blackDuck_right

; Table: Sprite Asset Frame Pointer List Table
; Format: dw SPRITE_<id>_FRAME_PTRS
sprite_asset_frame_ptr_table:
    dw SPRITE_0_FRAME_PTRS
    dw SPRITE_1_FRAME_PTRS
    dw SPRITE_2_FRAME_PTRS
    dw SPRITE_3_FRAME_PTRS
    dw SPRITE_4_FRAME_PTRS
    dw SPRITE_5_FRAME_PTRS
    dw SPRITE_6_FRAME_PTRS
    dw SPRITE_7_FRAME_PTRS
    dw SPRITE_8_FRAME_PTRS

; Sprite 0: hero1_right frame pointers
SPRITE_0_FRAME_PTRS:
    dw HERO1_RIGHT_0_F0_LAYER0
    dw HERO1_RIGHT_0_F1_LAYER0
    dw HERO1_RIGHT_0_F2_LAYER0
    dw HERO1_RIGHT_0_F3_LAYER0

