    dw BALL1_2_F2_LAYER1
    dw BALL1_2_F3_LAYER1
    dw BALL1_2_F4_LAYER1
    dw BALL1_2_F5_LAYER1

; Sprite 3: bird2 frame pointers
SPRITE_3_FRAME_PTRS:
