; ==================================================================
; DIRECTIONAL SPRITE LOOKUP TABLES
; Maps any sprite asset index to its directional variant index.
; If no directional variant exists, table points back to same index.
; ==================================================================
sprite_dir_left_table:
    db 6, 1, 2, 3, 7, 5, 6, 7, 5

sprite_dir_right_table:
    db 0, 1, 2, 3, 4, 8, 0, 4, 8

sprite_dir_up_table:
    db 0, 1, 2, 3, 4, 5, 6, 7, 8

sprite_dir_down_table:
    db 0, 1, 2, 3, 4, 5, 6, 7, 8

 
; ================================================================== 
; SPRITE CONFIGURATION TABLES 
; ================================================================== 

; Table: Entity Sprite Configuration 
; Format: db base_hw_sprite_index, layer_count 
entity_sprite_config: 
    db 0, 1 ; Entity 0 (PLACEHOLDER)
    db 1, 1 ; Entity 1 (PLACEHOLDER)
    db 2, 1 ; Entity 2 (PLACEHOLDER)
    db 3, 1 ; Entity 3 (PLACEHOLDER)
    db 4, 3 ; Entity 4 (bird1)
    db 7, 1 ; Entity 5 (PLACEHOLDER)
    db 8, 1 ; Entity 6 (PLACEHOLDER)
    db 9, 1 ; Entity 7 (PLACEHOLDER)
    db 10, 1 ; Entity 8 (PLACEHOLDER)
    db 11, 1 ; Entity 9 (PLACEHOLDER)
    db 12, 1 ; Entity 10 (PLACEHOLDER)
    db 13, 1 ; Entity 11 (PLACEHOLDER)
    db 14, 1 ; Entity 12 (PLACEHOLDER)
    db 15, 1 ; Entity 13 (PLACEHOLDER)
    db 16, 1 ; Entity 14 (PLACEHOLDER)
    db 17, 1 ; Entity 15 (PLACEHOLDER)
    db 18, 1 ; Entity 16 (PLACEHOLDER)
    ds 30, 0 ; Padding

; Table: Entity -> Sprite Asset Index (ROM initial values)
; Copied to RAM entity_sprite_asset_index at init
; Format: db sprite_asset_index (#FF = none)
entity_sprite_asset_index_init:
    db #FF ; Entity 0 (PLACEHOLDER)
    db #FF ; Entity 1 (PLACEHOLDER)
    db #FF ; Entity 2 (PLACEHOLDER)
    db #FF ; Entity 3 (PLACEHOLDER)
    db #01 ; Entity 4 (bird1)
    db #FF ; Entity 5 (PLACEHOLDER)
    db #FF ; Entity 6 (PLACEHOLDER)
    db #FF ; Entity 7 (PLACEHOLDER)
    db #FF ; Entity 8 (PLACEHOLDER)
    db #FF ; Entity 9 (PLACEHOLDER)
    db #FF ; Entity 10 (PLACEHOLDER)
    db #FF ; Entity 11 (PLACEHOLDER)
    db #FF ; Entity 12 (PLACEHOLDER)
    db #FF ; Entity 13 (PLACEHOLDER)
    db #FF ; Entity 14 (PLACEHOLDER)
    db #FF ; Entity 15 (PLACEHOLDER)
    db #FF ; Entity 16 (PLACEHOLDER)
    ds 15, #FF ; Padding
SPRITE_MAX_ENTITY_LAYERS EQU 3  ; Max HW sprite layers per entity

; Table: Hardware Sprite Layer Colors (ROM initial values - copied to RAM at init)
; Format: db color_index
sprite_layer_colors_init:
    ; Entity 0 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 1 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 2 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 3 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 4 (bird1) layers:
    db 1 ; Layer 0
    db 14 ; Layer 1
    db 6 ; Layer 2
    ; Entity 5 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 6 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 7 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 8 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 9 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 10 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 11 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 12 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 13 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 14 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 15 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ; Entity 16 (PLACEHOLDER) layers:
    db 15 ; Layer 0
    ds 13, 0 ; Padding

; Table: SM Sprite Layer Colors (for Action_ChangeSprite runtime color update)
; Format: SPRITE_MAX_ENTITY_LAYERS bytes per sprite asset
; Entry[i*SPRITE_MAX_ENTITY_LAYERS + j] = color for HW sprite slot j of sprite i
SM_SpriteLayerColorTable:
    db 1, 15, 6 ; Sprite 0: hero1_right
    db 1, 14, 6 ; Sprite 1: bird1
    db 4, 6, 0 ; Sprite 2: ball1
    db 15, 0, 0 ; Sprite 3: bird2
    db 4, 10, 0 ; Sprite 4: minipotato_right
    db 1, 15, 0 ; Sprite 5: blackDuck_left
    db 1, 15, 6 ; Sprite 6: hero1_left
    db 4, 10, 0 ; Sprite 7: minipotato_left
    db 1, 15, 0 ; Sprite 8: blackDuck_right

; ==================================================================
; SPRITE INITIALIZATION FUNCTIONS
; ==================================================================

init_sprites:
    ; Copy sprite_layer_colors_init (ROM) -> sprite_layer_colors (RAM)
    ld hl, sprite_layer_colors_init
    ld de, sprite_layer_colors
    ld bc, 32
    ldir
    call clear_all_sprites
    call load_sprite_patterns
    xor a
    ld (active_sprite_count), a
    ret

load_sprite_patterns:
